public class Main {
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st;
        String next() throws Exception { while(st==null||!st.hasMoreTokens()){ String line=br.readLine(); if(line==null)return null; st=new StringTokenizer(line);} return st.nextToken(); }
        long nextLong() throws Exception { return Long.parseLong(next()); }
        int nextInt() throws Exception { return Integer.parseInt(next()); }
    }
    static long firstFiveBoundary(long x){ return (x+4)/5; }
    public static void main(String[] args) throws Exception {
        FastScanner fs=new FastScanner(); int T=fs.nextInt();
        while(T-->0){
            long N=fs.nextLong(), K=fs.nextLong();
            if(K>=N){ System.out.println(0); continue; }
            // A later candidate changes day exactly when i%5==1. Count such i in (K,N].
            long count=firstFiveBoundary(N)-firstFiveBoundary(K);
            System.out.println(count);
        }
    }
}

