                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws Exception { return Integer.parseInt(next()); }
        long nextLong() throws Exception { return Long.parseLong(next()); }
    }
    public static void main(String[] args) throws Exception { FastScanner fs=new FastScanner(); int T=fs.nextInt(); while(T-->0){int N=fs.nextInt();String s=fs.next();char[] a=s.toCharArray();for(int i=0;i<N-1;i+=2){char tmp=a[i];a[i]=a[i+1];a[i+1]=tmp;}for(int i=0;i<N;i++)a[i]=(char)('z'-(a[i]-'a'));System.out.println(new String(a));}}
